typedef struct { size_t n_free; void **free_list; void *(*create)(void); void (*reset)(void *); } pool_t;

void *pool_acquire(pool_t *p) {
    pthread_mutex_lock(&p->m);
    void *obj = p->n_free ? p->free_list[--p->n_free] : NULL;   /* empty: decide policy */
    pthread_mutex_unlock(&p->m);
    if (!obj) obj = p->create();
    p->reset(obj);            /* storage reuse does not reset state */
    return obj;
}
/* pool_release(p, obj): push obj back under the same lock */
